48	    await Promise.all([collectAt(carriers[0]!, endpoint, docks[0]!, "sun"), collectAt(carriers[2]!, endpoint, docks[2]!, "sun")]);
49	    await Promise.all([collectAt(carriers[1]!, endpoint, docks[1]!, "sun"), collectAt(carriers[3]!, endpoint, docks[3]!, "sun")]);
50	    expect(room.ledgerState.rubbings.filter((rubbing) => rubbing.type === "sun").every((rubbing) => rubbing.location.kind === "player")).toBe(true);
