9	
10	/**
11	 * Records every sector name the sea shows from now on, as the page reports it (`data-sector-name` on the game): a
12	 * MutationObserver catches a name however briefly it shows. `sectorNamesSeen(page)` returns them.
13	 */
14	async function recordSectorNames(page: Page): Promise<void> {
15	  await page.evaluate(() => {
16	    const seen: string[] = [];
17	    (window as unknown as { __sectorNames: string[] }).__sectorNames = seen;
18	    const game = document.querySelector<HTMLElement>('[data-testid="game"]')!;
19	    new MutationObserver(() => seen.push(game.dataset["sectorName"] ?? "")).observe(game, { attributes: true, attributeFilter: ["data-sector-name"] });
20	  });
21	}
22	
23	async function sectorNamesSeen(page: Page): Promise<string[]> {
24	  return page.evaluate(() => (window as unknown as { __sectorNames: string[] }).__sectorNames);
25	}
