27	test("two browsers start a private match; the host opens the journal with M and reads its start rumor, moors at a dock, buys a targeted rumor with the keyboard and sees its gold drop by 25 and a new entry marked targeted; the guest's page never shows the host's rumors [scenario:rumor-journal]", async ({ browser, request }, testInfo) => {
28	  test.setTimeout(90_000);
29	  const hostContext = await browser.newContext();
30	  const guestContext = await browser.newContext();
31	  try {
32	    const host = await hostContext.newPage();
33	    const guest = await guestContext.newPage();
34	    const code = await createMatch(host);
35	    await joinMatch(guest, code);
36	    await startMatch(host, guest);
37	    const hostId = await selfId(host);
38	
39	    // M opens the journal: its start rumor names a type and an island (or a sector), with its reason.
