41	    await expect(journal).toBeHidden();
42	    await host.keyboard.press("m");
43	    await expect(journal).toBeVisible();
44	    const start = rumors(host).and(host.locator('[data-reason="start"]'));
45	    await expect(start).toHaveCount(1);
